  cout << "Floating Point Number: " << yytext << endl;
}

[0-9]+ {
  cout << "Integer Number: " << yytext << endl;
}

\"[^\"]*\" {
  cout << "String Literal: " << yytext << endl;
}

"+"|"-"|"*"|"/"|"=" {
  cout << "Operator: " << yytext << endl;
}

"("|")"|"{"|"}"|";"|"," {
  cout << "Special Symbol: " << yytext << endl;
}

[ \t\n]+ {
   // Ignore spaces and new lines
}

.{
     cout << "Unknown Character: " << yytext << endl;
}

%%

