#include <stdio.h>
#include <string.h>
#include <stdlib.h>

struct symtab
{
   char symbol[20];
   int address;
};

struct littab
{
   char literal[20];
   int address;
};

int main()
{
  FILE *fp;
  char w1[20], w2[20], w3[20];

  struct symtab s[10];
  struct littab l[10];

  int lc = 0;
  int scount = 0;
  int lcount = 0;

  fp = fopen("input.txt", "r");

if (fp == NULL)
{
   printf("File not found.\n");
   return 0;
}

while (fscanf(fp, "%s", w1) != EOF)
{
  if (strcmp(w1, "START") == 0)
  {
     fscanf(fp, "%d", &lc);
  }

  else if (strcmp(w1, "MOVER") == 0)
  {
    fscanf(fp, "%s %s", w2, w3);

      if (w3[0] == '=')
      {
         strcpy(l[lcount].literal, w3);
         l[lcount].address = -1;
         lcount++;
      }

      lc++;
  }

  else if (strcmp(w1, "MOVEM") == 0)
  {
    fscanf(fp, "%s %s", w2, w3);
    lc++;
  }

  else if (strcmp(w1, "END") == 0)
  {
    int i;
    for (i = 0; i < lcount; i++)
    {
      l[i].address = lc;
      lc++;
    }
  }

  else
  {
    strcpy(s[scount].symbol, w1);

      fscanf(fp, "%s %s", w2, w3);

      if (strcmp(w2, "DS") == 0)
      {
         s[scount].address = lc;
         lc += atoi(w3);
         scount++;

                       }
                   }
               }

               fclose(fp);

               printf("\nSYMTAB\n");
               printf("Symbol\tAddress\n");

               int i;
               for (i = 0; i < scount; i++)
                 printf("%s\t%d\n", s[i].symbol, s[i].address);

               printf("\nLITTAB\n");
               printf("Literal\tAddress\n");

               for (i = 0; i < lcount; i++)
                 printf("%s\t%d\n", l[i].literal, l[i].address);

               return 0;
                 }

