char stack[20][10];
int top = -1;

int temp = 1;

struct quad
{
   char op;
   char arg1[10];
   char arg2[10];
   char result[10];
};

struct quad q[20];
int count = 0;

void push(char *s)
{
  strcpy(stack[++top], s);
}

char* pop()
{
  return stack[top--];
}

void generate(char op)
{
  char *op2 = pop();
  char *op1 = pop();
  char res[10];

  sprintf(res, "t%d", temp++);

  q[count].op = op;
  strcpy(q[count].arg1, op1);
  strcpy(q[count].arg2, op2);
  strcpy(q[count].result, res);

  push(res);
  count++;
}
