#include <stdio.h>
#include <string.h>
#include <stdlib.h>

char input[100];
char *token;


void type();
void simple();
void match(char *expected);


void match(char *expected)
{
  if (token != NULL && strcmp(token, expected) == 0)
  {
     token = strtok(NULL, " ");
  }
  else
  {
     printf("Parsing Error: Expected '%s'\n", expected);
     exit(0);
  }
}


void simple()
{
  if (token == NULL)
  {
     printf("Parsing Error\n");
     exit(0);
  }

    if (strcmp(token, "integer") == 0)
    {
       match("integer");
    }
    else if (strcmp(token, "char") == 0)
    {
       match("char");
    }
    else if (strcmp(token, "num") == 0)
    {
       match("num");
       match("dotdot");
       match("num");
    }
    else
    {
       printf("Parsing Error in simple\n");
       exit(0);
    }
}


void type()
{
  if (token == NULL)
  {
     printf("Parsing Error\n");
     exit(0);
  }

    if (strcmp(token, "integer") == 0 ||
       strcmp(token, "char") == 0 ||
       strcmp(token, "num") == 0)
    {
       simple();
    }
    else if (strcmp(token, "^") == 0)
    {
       match("^");
       match("id");
    }
    else if (strcmp(token, "array") == 0)
    {
       match("array");
       match("[");
       simple();
       match("]");
       match("of");
       type();
    }
    else
    {
       printf("Parsing Error in type\n");
       exit(0);
    }
}

int main()
{
  printf("Enter input tokens separated by spaces:\n");
  fgets(input, sizeof(input), stdin);

    input[strcspn(input, "\n")] = '\0';

    token = strtok(input, " ");

    type();

    if (token == NULL)
       printf("String Accepted.\n");
    else
       printf("String Rejected.\n");

    return 0;
}
